  if (!m.theme && m.group) m.theme = m.themeOver ? Object.assign({}, SX.M[SX.GROUP[m.group].lead].theme, m.themeOver) : SX.M[SX.GROUP[m.group].lead].theme;   // 同一山群共用主峰的步道外觀；themeOver 只改其中幾項
